import { calculateElementDynamicHeight } from '@/config/layoutRegistry.js';
import type { Scene, SceneElement } from '@/types/scene';
import { assignGlobalDoodles } from './metaphorMatcherService.ts';
import { DURATION_BOUNDS, estimateSceneDurationSec } from '../config/pacingConfig';
import { applyAiWordAnchors } from '../utils/wordTimeline';

// ── SSOT CONSTANTS ───────────────────────────────────────────────────────────

// Nhịp đọc & giới hạn thời lượng: xem src/config/pacingConfig.js

export interface WizardNormalizerOptions {
  lang?: 'vi' | 'en';
  /** false: bỏ phụ đề (cả phụ đề AI tạo lẫn phụ đề tự chèn). Mặc định true */
  captions?: boolean;
}

// ── SUB-NORMALIZERS ──────────────────────────────────────────────────────────

/**
 * Deep Topological Knowledge Graph Healer:
 * Disambiguates duplicate IDs, breaks cyclic references, reconnects orphans and isolated island clusters to Root.
 */
export function healKnowledgeGraph(el: SceneElement): SceneElement {
  const target = { ...el } as any;
  const data = target.knowledgeGraphData ? { ...target.knowledgeGraphData } : target;
  let nodes = Array.isArray(data.nodes) ? [...data.nodes] : [];

  if (nodes.length === 0) {
    nodes = [{ id: 'root', label: target.content || 'Chủ đề chính', tier: 0 }];
  }

  // 1. Sanitize & Disambiguate duplicate IDs
  const seenIds = new Set<string>();
  nodes = nodes.map((n: any, idx: number) => {
    let rawId = String(n.id || `node_${idx + 1}`).trim();
    if (seenIds.has(rawId)) {
      rawId = `${rawId}_${idx + 1}`;
    }
    seenIds.add(rawId);
    return {
      ...n,
      id: rawId,
      label: String(n.label || n.title || `Khái niệm ${idx + 1}`).trim(),
    };
  });

  const nodeMap = new Map<string, any>(nodes.map((n: any) => [n.id, n]));

  // 2. Identify or promote single Root (Tier 0)
  let rootNode = nodes.find((n: any) => n.tier === 0);
  if (!rootNode) {
    rootNode = nodes[0];
    rootNode.tier = 0;
    rootNode.parentId = undefined;
  }
  const rootId = rootNode.id;

  // 3. Cycle Detection, Phantom Parent Fixing & Island Reconnection
  nodes.forEach((n: any) => {
    if (n.id === rootId) {
      n.parentId = undefined;
      n.tier = 0;
      return;
    }

    // Phantom parent check
    if (!n.parentId || !nodeMap.has(n.parentId) || n.parentId === n.id) {
      n.parentId = rootId;
      n.tier = 1;
      return;
    }

    // Cycle & Island Detection: Trace ancestor path to root
    let curr = n.parentId;
    const lineage = new Set<string>([n.id]);
    let reachesRoot = false;

    while (curr) {
      if (curr === rootId) {
        reachesRoot = true;
        break;
      }
      if (lineage.has(curr)) {
        // Detected closed loop in an island or ancestor chain!
        break;
      }
      lineage.add(curr);
      const parentNode = nodeMap.get(curr);
      curr = parentNode ? parentNode.parentId : null;
    }

    // If it forms a loop or doesn't reach root, break loop and reconnect to root
    if (!reachesRoot) {
      n.parentId = rootId;
      n.tier = 1;
    }
  });

  data.nodes = nodes;
  data.rootId = rootId;
  target.knowledgeGraphData = data;
  return target;
}

/**
 * Table Schema Healer:
 * Enforces valid 2D array, sanitizes non-string values, repairs uneven rows.
 */
export function healTable(el: SceneElement): SceneElement {
  const target = { ...el } as any;
  if (!target.tableData && target.table) target.tableData = target.table;
  let tableData = target.tableData;

  if (!tableData || typeof tableData !== 'object') {
    tableData = { headers: ['Thuộc tính', 'Giá trị'], rows: [['Mục 1', 'Dữ liệu']] };
  }

  let headers = Array.isArray(tableData.headers)
    ? tableData.headers.map((h: any) => String(h || '').trim())
    : ['Cột 1', 'Cột 2'];
  if (headers.length === 0) headers = ['Cột 1', 'Cột 2'];

  let rows = Array.isArray(tableData.rows) ? tableData.rows : [];
  const colCount = headers.length;

  rows = rows.map((r: any, rIdx: number) => {
    if (!Array.isArray(r)) {
      return Array(colCount).fill(`Dòng ${rIdx + 1}`);
    }
    const sanitizedRow = r.map((cell: any) =>
      cell === null || cell === undefined ? '' : String(cell).trim()
    );
    // Pad row if it has fewer columns than headers
    while (sanitizedRow.length < colCount) {
      sanitizedRow.push('-');
    }
    // Truncate if it has more columns than headers
    return sanitizedRow.slice(0, colCount);
  });

  if (rows.length === 0) {
    rows = [Array(colCount).fill('-')];
  }

  target.tableData = { headers, rows };
  return target;
}

// ── MAIN 5-PASS NORMALIZER ───────────────────────────────────────────────────

/**
 * Generative SVG Self-Healing:
 * Ensures formula is present and valid from the mathematical whitelist.
 */
export function healGenerativeSvg(el: SceneElement): SceneElement {
  const target = { ...el };
  const VALID_FORMULAS = [
    'quantum-orbit', 'lorenz-attractor', 'dna-helix', 'rose-curve',
    'exponential-surge', 'fibonacci-spiral', 'harmonic-wave', 'singularity-vortex',
    'network-mesh', 'bifurcation-tree', 'neural-pulse', 'cyber-shield',
    'spacetime-grid', 'lissajous-curve', 'mobius-loop', 'double-pendulum',
    'ecg-heartbeat', 'tesseract-hypercube', 'streamline-flow', 'torus-field'
  ];

  if (target.formula && !VALID_FORMULAS.includes(target.formula)) {
    target.formula = 'quantum-orbit';
  }

  if (!target.formula && !target.svgContent && (!target.paths || !target.paths.length)) {
    target.formula = 'quantum-orbit';
  }

  if (!target.width) target.width = 220;
  if (!target.height) target.height = 220;
  if (!target.accentColor && !target.color) target.accentColor = '#BEFF01';
  if (!target.secondaryColor) target.secondaryColor = '#00F2FE';

  return target;
}

/**
 * Normalizes all scenes generated by the AI Wizard Modal.
 * Transforms raw, potentially broken LLM output into a mathematically sound,
 * properly paced, and collision-free scene list for video rendering.
 */
export function normalizeWizardScenes(
  rawScenes: any[],
  options: WizardNormalizerOptions = {}
): Scene[] {
  if (!Array.isArray(rawScenes)) return [];
  const lang = options.lang === 'en' ? 'en' : 'vi';

  const normalizedScenes = rawScenes.map((rawScene, sceneIdx) => {
    if (!rawScene || typeof rawScene !== 'object') {
      return {
        id: `scene_${Date.now()}_${sceneIdx}`,
        name: `Cảnh ${sceneIdx + 1}`,
        description: '',
        duration: DURATION_BOUNDS.MIN_SEC,
        bgColor: '#080a0f',
        voiceoverText: '',
        elements: [],
      } as Scene;
    }

    const scene: Scene = {
      ...rawScene,
      id: rawScene.id || `scene_${sceneIdx + 1}_${Math.random().toString(36).slice(2, 6)}`,
      name: rawScene.name || `Cảnh ${sceneIdx + 1}`,
      description: rawScene.description || '',
      bgColor: rawScene.bgColor || '#080a0f',
      elements: Array.isArray(rawScene.elements) ? [...rawScene.elements] : [],
    };

    // --- PASS 1: ADAPTIVE PACING MATH (Safe Baseline) ---
    const voiceText = (scene.voiceoverText || '').trim();

    // --- PASS 2: DURATION CLAMP & TTS PRECEDENCE ---
    // If scene already has audio duration from actual TTS generation, TTS duration takes precedence
    const hasExplicitAudio =
      typeof (scene as any).audioDuration === 'number' && (scene as any).audioDuration > 0;
    const hasAudioUrl = Boolean(scene.voiceoverUrl && scene.duration && scene.duration > 0);

    if (hasExplicitAudio) {
      scene.duration = Math.max(
        DURATION_BOUNDS.ABSOLUTE_AUDIO_MIN_SEC,
        Math.round((scene as any).audioDuration * 10) / 10
      );
    } else if (hasAudioUrl) {
      scene.duration = Math.max(
        DURATION_BOUNDS.ABSOLUTE_AUDIO_MIN_SEC,
        Math.round(scene.duration * 10) / 10
      );
    } else {
      // Enforce mathematical baseline clamped within [MIN_SEC, MAX_SEC]
      scene.duration = estimateSceneDurationSec(voiceText, lang);
    }

    // --- PASS 3, 4 & 5: ELEMENTS, DYNAMIC HEIGHT & CAPTION SYNC ---
    let elements = scene.elements;
    let hasCaptionElement = false;

    elements = elements.map((rawEl, elIdx) => {
      if (!rawEl || typeof rawEl !== 'object') {
        return {
          id: `el_${sceneIdx}_${elIdx}`,
          type: 'text',
          content: '',
          left: 20,
          top: 100,
          width: 320,
          height: 40,
        } as SceneElement;
      }

      let el: SceneElement = { ...rawEl };
      if (!el.id) {
        el.id = `el_${sceneIdx}_${elIdx}_${Math.random().toString(36).slice(2, 6)}`;
      }

      // PASS 3: Widget-Specific Self-Healing
      if (el.type === 'knowledge-graph') {
        el = healKnowledgeGraph(el);
      } else if (el.type === 'table') {
        el = healTable(el);
      } else if (el.type === 'generative-svg') {
        el = healGenerativeSvg(el);
      }

      // PASS 3B: Neo animation vào lời thoại theo gợi ý anchorWord của AI
      el = applyAiWordAnchors(el, voiceText);

      // PASS 4: Dynamic Box-Model Contract H = f(N)
      if (['checklist', 'timeline', 'table', 'quote-box'].includes(el.type)) {
        el.height = calculateElementDynamicHeight(el);
      }

      // PASS 5: Caption Sync Detection
      if (el.type === 'caption') {
        hasCaptionElement = true;
        el.content = voiceText; // Force 1:1 synchronization with voiceoverText
      }

      return el;
    });

    // Người dùng tắt phụ đề ở wizard → bỏ mọi phụ đề, không tự chèn
    if (options.captions === false) {
      scene.elements = elements.filter((el: SceneElement) => el.type !== 'caption');
      return scene;
    }

    // If no caption element exists, auto-inject one for accessibility
    if (!hasCaptionElement && voiceText) {
      elements.push({
        id: `caption_${sceneIdx}_${Math.random().toString(36).slice(2, 6)}`,
        type: 'caption',
        content: voiceText,
        left: 20,
        top: 520,
        width: 320,
        height: 60,
        fontSize: 18,
      } as SceneElement);
    }

    scene.elements = elements;
    return scene;
  });

  return assignGlobalDoodles(normalizedScenes);
}
